    TreeNode<T> parent = node.getParent();
    TreeNode<T> left = node.getLeft();
    TreeNode<T> right = node.getRight();
    node.setParent(right);
    right.setParent(node);
    right.setLeft(node);

    if (left != null) {
        left.setParent(node);
    }

    if (parent != null) {
        if (parent.getLeft() == node) {
            parent.setLeft(right);
        } else {
            parent.setRight(right);
        }
    }

