  int count = 0;
  int i, j, start = -1;
  if (str == null || sub == null) return 0;
  for (i = 0; i < sub.length(); i++) {
    start = str.indexOf(sub.charAt(i), start + 1);
    if (start >= 0) {
      j = start;
      while (j < str.length() && j < i + sub.length()) {
        if (charAt(j++) != sub.charAt(i + j - start)) break;
      }
      if (j >= str.length() || j > i + sub.length()) {
        count++;
        i = j - 1;
      }
    }
  }
  return count;
}

